files.content:
.root,
.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #1e4d8c;
  --vt-ink: #152b42;
  --vt-ink-soft: #5d6b7a;
  --vt-on-deep: #ffffff;
  --vt-accent: #2c5fa1;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #1e4d8c;
  --vt-accent-on-deep: #c8e0f7;
  --vt-line: #dbeaf5;
  position: relative;
  margin: 0;
  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: 'Nunito Sans', sans-serif;
  line-height: 1.6;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(h1, h2, h3, h4, h5, h6, p, ul) {
  margin: 0;
}

.root ul {
  padding: 0;
  list-style: none;
}

.root img {
  max-width: 100%;
  display: block;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent-on-deep);
  outline-offset: 2px;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding-left: 24px;
  padding-right: 24px;
}

.topbar {
  background: var(--vt-accent);
  padding: 10px 0;
}

.topbar .container {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}

.topbarText {
  margin: 0;
  color: var(--vt-on-accent);
  font-size: 14px;
}

.topbarPhone {
  margin-left: auto;
  color: var(--vt-on-accent);
  font-weight: 700;
  font-size: 14px;
}

.nav {
  position: absolute;
  top: 46px;
  left: 0;
  right: 0;
  z-index: 20;
  padding: 18px 0;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.logo {
  display: inline-flex;
}

.brand {
  color: var(--vt-on-deep);
  font-size: 22px;
  font-weight: 700;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 28px;
}

.navLinks a {
  color: var(--vt-on-deep);
  font-size: 15px;
  font-weight: 600;
  opacity: 0.9;
}

.navLinks a:hover {
  color: var(--vt-accent-on-deep);
  opacity: 1;
}

.navCta {
  border: 2px solid var(--vt-on-deep);
  border-radius: 100px;
  padding: 8px 22px;
}

.hero {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 680px;
  padding: 160px 0 120px;
  background-size: cover;
  background-position: center;
  overflow: hidden;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: var(--vt-surface-deep);
  opacity: 0.55;
  z-index: 1;
}

.heroContent {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 820px;
}

.heroKicker {
  color: var(--vt-accent-on-deep);
  text-transform: uppercase;
  letter-spacing: 3px;
  font-weight: 700;
  font-size: 14px;
  margin-bottom: 16px;
}

.heroTitle {
  color: var(--vt-on-deep);
  font-size: clamp(40px, 6vw, 58px);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: 16px;
}

.heroLead {
  color: var(--vt-on-deep);
  font-size: 18px;
  max-width: 620px;
  margin: 0 auto 32px;
}

.heroActions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.root .btnPrimary,
.root .btnGhost {
  display: inline-block;
  border-radius: 100px;
  font-size: 16px;
  font-weight: 600;
  transition: background 0.3s, border-color 0.3s, color 0.3s;
}

.root .btnPrimary {
  background: var(--vt-accent-ink);
  color: var(--vt-on-accent);
  border: 2px solid transparent;
  padding: 14px 30px;
}

.root .btnPrimary:hover {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.root .btnGhost {
  border: 2px solid var(--vt-on-deep);
  color: var(--vt-on-deep);
  padding: 12px 28px;
}

.root .btnGhost:hover {
  background: var(--vt-on-deep);
  color: var(--vt-accent-ink);
}

.wave {
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 100%;
  height: 120px;
  z-index: 3;
  pointer-events: none;
}

.wave path {
  fill: var(--vt-surface);
}

.story {
  padding: 90px 0;
  background: var(--vt-surface);
}

.storyGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.sectionKicker {
  color: var(--vt-accent-ink);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 12px;
}

.sectionTitle {
  color: var(--vt-ink);
  font-size: 38px;
  line-height: 1.15;
  margin-bottom: 20px;
  font-weight: 800;
}

.storyIntro {
  color: var(--vt-ink-soft);
  font-size: 17px;
  margin-bottom: 16px;
}

.storyParagraph {
  color: var(--vt-ink-soft);
  margin-bottom: 12px;
}

.storyMedia {
  position: relative;
}

.storyImage {
  width: 100%;
  border-radius: 20px;
  object-fit: cover;
  aspect-ratio: 4 / 3;
  box-shadow: 0 16px 40px var(--vt-line);
}

.callCard {
  position: absolute;
  right: 16px;
  bottom: 16px;
  background: var(--vt-accent-ink);
  color: var(--vt-on-accent);
  border-radius: 10px;
  padding: 20px 24px;
  box-shadow: 0 8px 24px var(--vt-surface-deep);
}

.callCard strong {
  display: block;
  font-size: 15px;
  margin-bottom: 6px;
}

.callCard a {
  color: var(--vt-on-accent);
  font-size: 18px;
  font-weight: 700;
}

.services {
  padding: 90px 0;
  background: var(--vt-surface-2);
}

.sectionHead {
  margin-bottom: 44px;
}

.servicesGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.serviceCard {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 24px;
  background: var(--vt-surface);
  border: 1px solid var(--vt-line);
  border-radius: 10px;
  padding: 20px;
  box-shadow: 0 8px 24px var(--vt-line);
}

.serviceMedia {
  border-radius: 10px;
  overflow: hidden;
}

.serviceImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  aspect-ratio: 1;
}

.serviceInfo {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.serviceNum {
  color: var(--vt-accent-ink);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 1px;
  margin-bottom: 8px;
}

.serviceTitle {
  color: var(--vt-ink);
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 10px;
}

.serviceDesc {
  color: var(--vt-ink-soft);
  font-size: 15px;
}

.contact {
  padding: 90px 0;
  background: var(--vt-surface);
}

.contactGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.contactInfo .sectionTitle {
  margin-bottom: 12px;
}

.contactText {
  color: var(--vt-ink-soft);
  margin-bottom: 12px;
}

.contactPhone {
  display: inline-block;
  color: var(--vt-accent-ink);
  font-size: 28px;
  font-weight: 800;
  margin-bottom: 12px;
}

.contactHours {
  color: var(--vt-ink-soft);
}

.socialInline {
  display: flex;
  gap: 10px;
  margin-top: 16px;
}

.mapWrap {
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 16px 40px var(--vt-line);
  min-height: 320px;
}

.mapWrap iframe {
  width: 100%;
  height: 100%;
  min-height: 320px;
  border: 0;
}

.footer {
  background: var(--vt-surface-deep);
  color: var(--vt-on-accent);
  padding-top: 60px;
}

.footerTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 40px;
}

.footerBrand {
  color: var(--vt-on-accent);
}

.footerTag {
  color: var(--vt-on-accent);
  margin: 0;
}

.footerGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
  padding-bottom: 40px;
}

.footerCol h4 {
  color: var(--vt-on-accent);
  font-size: 18px;
  margin-bottom: 14px;
}

.footerCol p,
.footerCol a,
.footerCol li {
  color: var(--vt-on-accent);
  font-size: 15px;
}

.footerCol a:hover {
  color: var(--vt-on-accent);
}

.footerCol ul li {
  margin-bottom: 8px;
}

.footerBottom {
  border-top: 1px solid var(--vt-accent-on-deep);
  padding: 20px 0;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  color: var(--vt-on-accent);
  font-size: 14px;
}

.root .callFab {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 100;
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--vt-accent-ink);
  color: var(--vt-on-accent);
  border-radius: 100px;
  padding: 14px 24px;
  box-shadow: 0 8px 24px var(--vt-surface-deep);
  font-weight: 700;
}

.callFabIcon {
  font-size: 20px;
  line-height: 1;
}

@media (max-width: 900px) {
  .nav {
    position: static;
    background: var(--vt-surface-deep);
    padding: 12px 0;
  }

  .navIn {
    flex-wrap: wrap;
    justify-content: center;
  }

  .navLinks {
    flex-wrap: wrap;
    justify-content: center;
    gap: 16px;
    width: 100%;
  }

  .hero {
    min-height: 520px;
    padding: 80px 0;
  }

  .storyGrid,
  .contactGrid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .servicesGrid {
    grid-template-columns: 1fr;
  }

  .serviceCard {
    grid-template-columns: 1fr;
  }

  .serviceImage {
    aspect-ratio: 16 / 9;
  }

  .footerGrid {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .topbar .topbarText:nth-child(2) {
    display: none;
  }

  .topbarPhone {
    margin-left: 0;
  }

  .callFab {
    bottom: 16px;
    right: 16px;
    padding: 12px 18px;
    font-size: 14px;
  }
}

@media (max-width: 600px) {
  .sectionTitle {
    font-size: 30px;
  }

  .heroTitle {
    font-size: 36px;
  }

  .heroLead {
    font-size: 16px;
  }

  .footerTop {
    flex-direction: column;
    text-align: center;
  }

  .footerBottom {
    justify-content: center;
    text-align: center;
  }
}
